set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {createRequire} from 'node:module';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {NewsHttpDriver,NewsProxyPool} from './src/newsFlow/transport.mjs';import {NewsNetworkPool} from './src/newsFlow/networkPool.mjs';const root='/var/lib/news-flow/qc-alt25-20261122',require=createRequire('/opt/news-flow/current/package.json'),ch=require('cheerio'),routes=JSON.parse(fs.readFileSync(root+'/routes.json')),entry=routes.sites.find(s=>s.site==='edition.cnn.com'),links=entry.jobs.find(p=>p.links?.length).links.filter(p=>/\/20\d\d\/\d\d\//.test(p.url)),registry=await loadNewsRegistry(),source=registry.sources.get('edition.cnn.com'),pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),network=new NewsNetworkPool({workers:1}),driver=new NewsHttpDriver({state:{cacheResponses:false,failedUrl:()=>false,request:()=>null,reserve:()=>true,cache:()=>null,completeHttpResponse:()=>{}},network,pool,allowedDomains:[...registry.allowedDomains,'lite.cnn.com'],siteCooldown:false,maxWireRequests:8}),r={at:new Date().toISOString(),samples:[]};try{for(const j of links.slice(0,6)){const p=await driver.get('qc-alt25-cnn-samples',j.url,source.config,[],{reviewFailed:true,taskRole:'article'}),o={url:j.url,statusCode:p.statusCode,error:p.error,finalUrl:p.finalUrl};if(p.html){o.file=root+'/evidence/'+createHash('sha256').update(p.html).digest('hex')+'.gz';fs.writeFileSync(o.file,gzipSync(p.html));const $=ch.load(p.html);o.head=$('head').html();o.body=$('body').text().replace(/\s+/g,' ').trim().slice(0,1600);o.bodyStart=$('body').html()?.slice(0,4000);o.footer=$('a[href]').toArray().map(e=>({href:$(e).attr('href'),text:$(e).text().trim()})).slice(-8);}r.samples.push(o);fs.writeFileSync(root+'/cnn-samples.json',JSON.stringify(r,null,2));console.log(JSON.stringify(o));}}finally{await network.close();}
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-alt25-20261122/cnn-samples.json "$upload_dir/.qc-alt25-cnn-samples.json"
